-- ===========================================================================
-- Part 2: constraints, RLS, privileges and triggers (hand-written)
-- ===========================================================================

ALTER TABLE "sales"
  ADD CONSTRAINT "sales_invoice_no_positive" CHECK ("invoice_no" >= 1),
  ADD CONSTRAINT "sales_amounts_non_negative" CHECK (
    "subtotal_poisha" >= 0 AND "line_discount_poisha" >= 0 AND "sale_discount_poisha" >= 0
    AND "tax_poisha" >= 0 AND "total_poisha" >= 0 AND "paid_poisha" >= 0 AND "due_poisha" >= 0
  ),
  ADD CONSTRAINT "sales_total_adds_up" CHECK (
    "total_poisha" = "subtotal_poisha" - "line_discount_poisha" - "sale_discount_poisha"
  ),
  ADD CONSTRAINT "sales_paid_plus_due" CHECK ("paid_poisha" + "due_poisha" = "total_poisha"),
  ADD CONSTRAINT "sales_tax_within_total" CHECK ("tax_poisha" <= "total_poisha"),
  ADD CONSTRAINT "sales_discount_input_pair" CHECK (
    ("sale_discount_type" IS NULL AND "sale_discount_value" IS NULL)
    OR ("sale_discount_type" = 'amount' AND "sale_discount_value" >= 0)
    OR ("sale_discount_type" = 'percent' AND "sale_discount_value" BETWEEN 0 AND 10000)
  ),
  ADD CONSTRAINT "sales_void_fields" CHECK (
    ("status" = 'completed' AND "voided_at" IS NULL AND "voided_by_user_id" IS NULL AND "void_reason" IS NULL)
    OR ("status" = 'voided' AND "voided_at" IS NOT NULL AND "voided_by_user_id" IS NOT NULL
        AND length(btrim(coalesce("void_reason", ''))) >= 3)
  );

ALTER TABLE "sale_items"
  ADD CONSTRAINT "sale_items_line_no_positive" CHECK ("line_no" >= 1),
  ADD CONSTRAINT "sale_items_quantity_positive" CHECK ("quantity" > 0),
  ADD CONSTRAINT "sale_items_amounts_non_negative" CHECK (
    "unit_price_poisha" >= 0 AND "gross_poisha" >= 0 AND "line_discount_poisha" >= 0
    AND "sale_discount_share_poisha" >= 0 AND "total_poisha" >= 0 AND "tax_poisha" >= 0
  ),
  ADD CONSTRAINT "sale_items_total_adds_up" CHECK (
    "total_poisha" = "gross_poisha" - "line_discount_poisha" - "sale_discount_share_poisha"
  ),
  ADD CONSTRAINT "sale_items_tax_within_total" CHECK ("tax_poisha" <= "total_poisha"),
  ADD CONSTRAINT "sale_items_vat_rate_range" CHECK ("vat_rate_bp" BETWEEN 0 AND 10000),
  ADD CONSTRAINT "sale_items_discount_input_pair" CHECK (
    ("discount_type" IS NULL AND "discount_value" IS NULL)
    OR ("discount_type" = 'amount' AND "discount_value" >= 0)
    OR ("discount_type" = 'percent' AND "discount_value" BETWEEN 0 AND 10000)
  );

ALTER TABLE "sale_payments"
  ADD CONSTRAINT "sale_payments_amount_non_negative" CHECK ("amount_poisha" >= 0),
  -- Cash records what was handed over and the change; other methods do not.
  ADD CONSTRAINT "sale_payments_cash_change" CHECK (
    ("method" = 'cash' AND "tendered_poisha" >= "amount_poisha"
       AND "change_poisha" = "tendered_poisha" - "amount_poisha")
    OR ("method" <> 'cash' AND "tendered_poisha" IS NULL AND "change_poisha" IS NULL)
  );

ALTER TABLE "invoice_counters"
  ADD CONSTRAINT "invoice_counters_non_negative" CHECK ("last_value" >= 0);

ALTER TABLE "idempotency_keys"
  ADD CONSTRAINT "idempotency_keys_key_format" CHECK ("key" ~ '^[A-Za-z0-9_-]{8,100}$'),
  ADD CONSTRAINT "idempotency_keys_scope_present" CHECK (length("scope") BETWEEN 1 AND 40);

-- Row Level Security: tenant isolation on every new table.
ALTER TABLE "sales" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sales" FORCE ROW LEVEL SECURITY;
CREATE POLICY "sales_tenant_isolation" ON "sales"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

ALTER TABLE "sale_items" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sale_items" FORCE ROW LEVEL SECURITY;
CREATE POLICY "sale_items_tenant_isolation" ON "sale_items"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

ALTER TABLE "sale_payments" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "sale_payments" FORCE ROW LEVEL SECURITY;
CREATE POLICY "sale_payments_tenant_isolation" ON "sale_payments"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

ALTER TABLE "invoice_counters" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "invoice_counters" FORCE ROW LEVEL SECURITY;
CREATE POLICY "invoice_counters_tenant_isolation" ON "invoice_counters"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

ALTER TABLE "idempotency_keys" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "idempotency_keys" FORCE ROW LEVEL SECURITY;
CREATE POLICY "idempotency_keys_tenant_isolation" ON "idempotency_keys"
  USING ("tenant_id" = app_current_tenant_id())
  WITH CHECK ("tenant_id" = app_current_tenant_id());

-- Privileges. Sales are financial records: never deleted, and the only columns
-- app_user may ever update are the void columns. Lines and payments are append-only.
REVOKE UPDATE, DELETE ON "sales" FROM app_user;
GRANT UPDATE ("status", "voided_at", "voided_by_user_id", "void_reason") ON "sales" TO app_user;
REVOKE UPDATE, DELETE ON "sale_items" FROM app_user;
REVOKE UPDATE, DELETE ON "sale_payments" FROM app_user;
REVOKE DELETE ON "invoice_counters" FROM app_user;
REVOKE DELETE ON "idempotency_keys" FROM app_user;

-- A voided sale stays voided: it can be voided once and never changed again.
CREATE FUNCTION prevent_change_after_void() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.status = 'voided' THEN
    RAISE EXCEPTION 'sale_already_voided' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "sales_void_guard"
  BEFORE UPDATE ON "sales"
  FOR EACH ROW EXECUTE FUNCTION prevent_change_after_void();

-- At commit, a sale's totals must equal the sums of its lines and payments, and it
-- must have at least one line. Deferred, so the sale, lines and payments can be
-- inserted in any order inside one transaction; fires again if a line or payment is
-- added later, so no sale can be made inconsistent afterwards either.
CREATE FUNCTION check_sale_consistency(p_sale_id uuid) RETURNS void
  LANGUAGE plpgsql
AS $$
DECLARE
  s RECORD;
  lines RECORD;
  paid bigint;
BEGIN
  SELECT * INTO s FROM sales WHERE id = p_sale_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sale_not_visible' USING ERRCODE = 'P0001';
  END IF;
  SELECT count(*) AS n,
         COALESCE(SUM(gross_poisha), 0) AS gross,
         COALESCE(SUM(line_discount_poisha), 0) AS line_discount,
         COALESCE(SUM(sale_discount_share_poisha), 0) AS share,
         COALESCE(SUM(total_poisha), 0) AS total,
         COALESCE(SUM(tax_poisha), 0) AS tax
    INTO lines
    FROM sale_items WHERE tenant_id = s.tenant_id AND sale_id = s.id;
  SELECT COALESCE(SUM(amount_poisha), 0) INTO paid
    FROM sale_payments WHERE tenant_id = s.tenant_id AND sale_id = s.id;
  IF lines.n = 0
     OR lines.gross <> s.subtotal_poisha
     OR lines.line_discount <> s.line_discount_poisha
     OR lines.share <> s.sale_discount_poisha
     OR lines.total <> s.total_poisha
     OR lines.tax <> s.tax_poisha
     OR paid <> s.paid_poisha THEN
    RAISE EXCEPTION 'sale_totals_inconsistent' USING ERRCODE = 'P0001',
      DETAIL = format('sale %s', s.id);
  END IF;
END;
$$;

CREATE FUNCTION check_sale_consistency_trigger() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_TABLE_NAME = 'sales' THEN
    PERFORM check_sale_consistency(NEW.id);
  ELSE
    PERFORM check_sale_consistency(NEW.sale_id);
  END IF;
  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER "sales_consistency"
  AFTER INSERT ON "sales"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_sale_consistency_trigger();

CREATE CONSTRAINT TRIGGER "sale_items_consistency"
  AFTER INSERT ON "sale_items"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_sale_consistency_trigger();

CREATE CONSTRAINT TRIGGER "sale_payments_consistency"
  AFTER INSERT ON "sale_payments"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION check_sale_consistency_trigger();
